settings_json.customCss:
/* 結い庵 — 明朝で組むための調整。
   顧客が「明朝」を選んだときに、そのまま気持ちよく読める値にしている。 */
:root{ --yui-ink:#2a2724; --yui-accent:#8a6a43; --yui-cream:#f7f4ef; --yui-line:#e2dcd2; }

body{ color:var(--yui-ink); background:#fff; }

/* 明朝は線が細い。字間と行送りを広げて、面で読ませる */
.lhp-section p, .lhp-faq-a, .lhp-price-desc, .lhp-col p{
  font-size:16.5px; line-height:2.05; letter-spacing:.02em; color:#3b3733;
}
@media(max-width:640px){
  .lhp-section p, .lhp-faq-a, .lhp-col p{ font-size:16px; line-height:1.95; }
}

/* 読み幅を上限で止める。1440pxで1行が長くなりすぎるのを防ぐ */
.lhp-section > p, .lhp-section-sub{ max-width:34em; margin-left:auto; margin-right:auto; }

/* 見出し。明朝の縦画を活かして、字間はやや詰める */
.lhp-section-title{
  font-size:clamp(21px,3.2vw,27px); letter-spacing:.06em; font-weight:600;
  color:var(--yui-ink); margin-bottom:.9em;
}
.lhp-section-title::after{
  content:""; display:block; width:34px; height:1px; background:var(--yui-accent);
  margin:.7em auto 0;
}

/* 節の間隔。既定は広すぎて、間が抜けて見える */
.lhp-section{ padding-top:clamp(48px,7vw,80px); padding-bottom:clamp(48px,7vw,80px); }

/* ヒーロー。写真を主役にして、文字は左下に寄せる */
.lhp-hero{ min-height:clamp(420px,72vh,640px); }
.lhp-hero-split .lhp-hero-inner{ gap:clamp(24px,4vw,56px); align-items:center; }
.lhp-hero-split-img{ border-radius:2px; overflow:hidden; aspect-ratio:4/3; }
.lhp-hero-split-img img{ width:100%; height:100%; object-fit:cover; }
.lhp-hero h1{ font-size:clamp(34px,6vw,58px); letter-spacing:.14em; font-weight:500; }
.lhp-hero-sub{ font-size:clamp(14px,2.2vw,17px); line-height:2; letter-spacing:.04em; opacity:.92; }
.lhp-btn-primary{
  background:var(--yui-accent); color:#fff; border-radius:2px;
  padding:16px 30px; letter-spacing:.08em; font-weight:500;
  min-height:52px; display:inline-flex; align-items:center;
}

/* 料金表。既定の青はサロンの色ではない */
.lhp-price-card{ border:1px solid var(--yui-line); border-radius:2px; box-shadow:none; }
.lhp-price-featured{ background:var(--yui-cream); border-color:var(--yui-accent); color:var(--yui-ink); }
.lhp-price-featured *{ color:var(--yui-ink) !important; }
.lhp-price-badge{ background:var(--yui-accent); color:#fff; letter-spacing:.08em; }
.lhp-price-amount{ font-size:30px; letter-spacing:.02em; }
.lhp-price-period{ font-size:15px; margin-left:2px; }
.lhp-price-features li{ font-size:14px; line-height:1.9; }
.lhp-price-btn{
  background:var(--yui-accent); color:#fff; border-radius:2px; letter-spacing:.06em;
  min-height:48px; display:flex; align-items:center; justify-content:center;
}

/* 写真。4:5で切り、間を詰める */
.lhp-gallery{ gap:10px; max-width:900px; margin:0 auto; }
.lhp-gallery-img{ aspect-ratio:4/5; object-fit:cover; border-radius:2px; }

/* スタイリスト。円は小さすぎたので大きくする */
.lhp-section [style*="border-radius:50%"]{ width:148px !important; height:148px !important; margin-bottom:16px !important; }
.lhp-section [style*="border-radius:50%"] + p{ font-size:16px; letter-spacing:.04em; }

/* 営業時間 */
.lhp-hours{ max-width:420px; margin:0 auto; }
.lhp-hours th,.lhp-hours td{ padding:12px 10px; border-bottom:1px solid var(--yui-line); }
.lhp-hours-note{ max-width:34em; margin:1.2em auto 0; font-size:14px; color:#6b645c; }

/* よくある質問 */
.lhp-faq{ max-width:40em; margin:0 auto; }
.lhp-faq-item{ border-bottom:1px solid var(--yui-line); }
.lhp-faq-q{ padding:18px 4px; font-weight:500; letter-spacing:.03em; min-height:56px; }

/* 予約。指で押せる大きさにする */
#booking input,#booking select,#booking textarea{
  min-height:52px; font-size:16px; border-radius:2px; border:1px solid var(--yui-line);
}
#booking button,.lhp-contact button{
  min-height:56px; font-size:16px; border-radius:2px; letter-spacing:.08em;
}

/* 見出しだけの節は、次の節と余白が二重になる。下の余白を落として1つにまとめる */
.lhp-section:has(> h2:only-child){ padding-bottom:0; }
.lhp-section:has(> h2:only-child) + .lhp-section{ padding-top:clamp(20px,2.4vw,28px); }
.lhp-section:has(> h2:only-child) h2{
  font-size:clamp(22px,3.4vw,30px); letter-spacing:.1em; font-weight:500; color:var(--yui-ink);
}
.lhp-section > p + p{ margin-top:1.4em; }

/* 固定CTAが出ているぶん、最後の節の下を空ける */
@media(max-width:640px){ .lhp-contact:last-of-type{ padding-bottom:32px; } }
